statements:
GRANT USAGE ON SCHEMA public TO anon, authenticated;
GRANT SELECT ON TABLE public.loop_titles TO anon, authenticated;
GRANT SELECT ON TABLE public.bridge_loop_publications TO anon, authenticated;

REVOKE ALL ON FUNCTION public.public_loop_catalog() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.public_loop_catalog() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.public_loop_catalog() TO service_role;
REVOKE SELECT ON TABLE public.loop_titles FROM anon, authenticated;
REVOKE SELECT ON TABLE public.bridge_loop_publications FROM anon, authenticated;

create table if not exists public.loop_viewer_profiles (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  display_name text not null check (length(btrim(display_name)) between 1 and 24),
  is_kids boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists loop_viewer_profiles_user_created_idx
  on public.loop_viewer_profiles (user_id, created_at);
alter table public.loop_viewer_profiles enable row level security;
drop policy if exists loop_viewer_profiles_select_own on public.loop_viewer_profiles;
create policy loop_viewer_profiles_select_own on public.loop_viewer_profiles
  for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists loop_viewer_profiles_insert_own on public.loop_viewer_profiles;
create policy loop_viewer_profiles_insert_own on public.loop_viewer_profiles
  for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists loop_viewer_profiles_update_own on public.loop_viewer_profiles;
create policy loop_viewer_profiles_update_own on public.loop_viewer_profiles
  for update to authenticated using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));
drop policy if exists loop_viewer_profiles_delete_own on public.loop_viewer_profiles;
create policy loop_viewer_profiles_delete_own on public.loop_viewer_profiles
  for delete to authenticated using (user_id = (select auth.uid()));
revoke all on public.loop_viewer_profiles from anon;
grant select, insert, update, delete on public.loop_viewer_profiles to authenticated;

create table if not exists public.loop_watchlists (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title_id text not null references public.loop_titles(id) on delete cascade,
  created_at timestamptz not null default now(),
  constraint loop_watchlists_user_title_key unique (user_id, title_id)
);
create index if not exists loop_watchlists_user_created_idx
  on public.loop_watchlists (user_id, created_at desc);
alter table public.loop_watchlists enable row level security;
drop policy if exists loop_watchlists_select_own on public.loop_watchlists;
create policy loop_watchlists_select_own on public.loop_watchlists
  for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists loop_watchlists_insert_own on public.loop_watchlists;
create policy loop_watchlists_insert_own on public.loop_watchlists
  for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists loop_watchlists_delete_own on public.loop_watchlists;
create policy loop_watchlists_delete_own on public.loop_watchlists
  for delete to authenticated using (user_id = (select auth.uid()));
revoke all on public.loop_watchlists from anon;
grant select, insert, delete on public.loop_watchlists to authenticated;

-- Restrict the legacy-link server role to row operations only.
-- Browser roles and PUBLIC retain no table privileges.
revoke all on table public.streamvista_legacy_links from public, anon, authenticated, service_role;
grant select, insert, update, delete on table public.streamvista_legacy_links to service_role;
